// "تفقه في الدين" content (generated by scripts/convert-fiqh.mjs).
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import { normalizeArabic } from "@/components/fiqh/normalize";

export type FiqhBlockType = "heading" | "text" | "verse" | "hadith" | "list";
export type FiqhBlock = { t: FiqhBlockType; x: string; r?: string };
export type FiqhTopic = { id: string; question: string; intro: string; steps?: boolean; blocks: FiqhBlock[] };
export type FiqhTopicRef = { id: string; question: string; steps?: boolean };
export type FiqhCategory = { id: string; title: string; subtitle: string; topics: FiqhTopicRef[] };
export type FiqhIndex = { title: string; subtitle: string; categories: FiqhCategory[] };

const load = cache(async <T>(file: string): Promise<T> =>
  JSON.parse(await fs.readFile(path.join(process.cwd(), "data/fiqh", file), "utf8")),
);

export const getFiqhIndex = () => load<FiqhIndex>("index.json");
export const getFiqhCategoryTopics = (id: string) => load<FiqhTopic[]>(`${id}.json`);

/** Every topic in reading order, with its category id. */
export const getFiqhOrder = cache(async () =>
  (await getFiqhIndex()).categories.flatMap((c) => c.topics.map((t) => ({ ...t, category: c.id }))),
);

/** Normalized full text per topic id, for the index search (like the app). */
export const getFiqhSearchIndex = cache(async () => {
  const { categories } = await getFiqhIndex();
  const out: Record<string, string> = {};
  for (const c of categories) {
    for (const t of await getFiqhCategoryTopics(c.id)) {
      out[t.id] = normalizeArabic(
        [t.question, t.intro, ...t.blocks.flatMap((b) => [b.x, b.r ?? ""])].join(" ").replace(/[ۖ-ۭ]/g, ""),
      ).replace(/\s+/g, " ");
    }
  }
  return out;
});
